-- 0003_review_fixes: fixes from the S03 adversarial review (ADR 0018). The first part was generated by
-- drizzle-kit from src/db/schema (constraints and indexes, reordered: unique targets before the foreign
-- keys that use them); the second part (functions, triggers, grants) is hand-written.
-- Locking: ADD CONSTRAINT UNIQUE/FOREIGN KEY and CREATE INDEX take SHARE / SHARE ROW EXCLUSIVE locks and
-- scan the table. Fine while the tables are empty (before the pilot); on a large live table use
-- CREATE INDEX CONCURRENTLY + ADD CONSTRAINT ... USING INDEX / NOT VALID + VALIDATE in a separate
-- procedure (the runner wraps each file in a transaction, see docs/DB.md 6).

-- ===================================================================================
-- Composite keys: an earning's node, store, job, attempt and payout record must agree (M10).
-- ===================================================================================
ALTER TABLE "nodes" ADD CONSTRAINT "nodes_id_store_key" UNIQUE("id","store_id");--> statement-breakpoint
ALTER TABLE "job_attempts" ADD CONSTRAINT "job_attempts_id_job_node_key" UNIQUE("id","job_id","node_id");--> statement-breakpoint
ALTER TABLE "payout_records" ADD CONSTRAINT "payout_records_id_store_key" UNIQUE("id","store_id");--> statement-breakpoint
ALTER TABLE "earnings" ADD CONSTRAINT "earnings_node_store_fk" FOREIGN KEY ("node_id","store_id") REFERENCES "public"."nodes"("id","store_id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "earnings" ADD CONSTRAINT "earnings_attempt_job_node_fk" FOREIGN KEY ("attempt_id","job_id","node_id") REFERENCES "public"."job_attempts"("id","job_id","node_id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "earnings" ADD CONSTRAINT "earnings_payout_record_store_fk" FOREIGN KEY ("payout_record_id","store_id") REFERENCES "public"."payout_records"("id","store_id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint

-- ===================================================================================
-- Indexes for the scheduler claim per model, the offer-timeout sweep and the M4 reconciliation.
-- ===================================================================================
CREATE INDEX "jobs_queue_model_idx" ON "jobs" USING btree ("model_id","priority" DESC NULLS LAST,"created_at","id") WHERE "jobs"."status" = 'queued';--> statement-breakpoint
CREATE INDEX "job_attempts_offered_sweep_idx" ON "job_attempts" USING btree ("offered_at") WHERE "job_attempts"."status" = 'offered';--> statement-breakpoint
CREATE INDEX "holds_active_account_idx" ON "holds" USING btree ("buyer_account_id") WHERE "holds"."status" = 'active';--> statement-breakpoint

-- ===================================================================================
-- M1 / M1-b: postings are appended in id order to a ledger transaction created by this DB transaction.
-- Review finding: (1) a posting with a smaller, client-chosen id (INSERT ... OVERRIDING SYSTEM VALUE)
-- added after SET CONSTRAINTS ... IMMEDIATE was never summed, because the deferred check only runs on
-- the transaction's highest id; (2) a posting whose ledger transaction was not yet visible (created by
-- another, uncommitted DB transaction) skipped the same-transaction check.
-- ===================================================================================
CREATE OR REPLACE FUNCTION binjari_ledger_posting_same_xact() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  tx_xid xid8;
BEGIN
  SELECT created_xid INTO tx_xid FROM public.ledger_transactions WHERE id = NEW.tx_id;
  -- Not visible = created by another DB transaction that has not committed (or does not exist):
  -- either way the posting is not from the creating transaction.
  IF NOT FOUND OR tx_xid <> pg_current_xact_id() THEN
    RAISE EXCEPTION 'posting for ledger transaction % must be inserted in the DB transaction that created it', NEW.tx_id
      USING ERRCODE = 'BJ004', TABLE = 'ledger_postings';
  END IF;
  -- The deferred balance check sums the transaction on its highest posting id, so every new posting
  -- must have a higher id than the ones before it (identity values do; chosen ids may not).
  IF EXISTS (SELECT 1 FROM public.ledger_postings WHERE tx_id = NEW.tx_id AND id >= NEW.id) THEN
    RAISE EXCEPTION 'postings of ledger transaction % must be appended in id order', NEW.tx_id
      USING ERRCODE = 'BJ001', TABLE = 'ledger_postings';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint

-- The app role keeps INSERT on every column of ledger_postings: Drizzle names the identity column in
-- its INSERT (`"id" ... VALUES (default, ...)`), which needs the column privilege. A chosen id cannot
-- bypass M1 any more because of the id-order check above.

-- ===================================================================================
-- Money records start in their initial state (review finding: M10 was only checked on UPDATE, so an
-- INSERT could create an already linked or settled record and skip the matured step).
-- ===================================================================================
CREATE FUNCTION binjari_money_record_insert_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_TABLE_NAME = 'holds' THEN
    IF NEW.status <> 'active' OR NEW.captured_amount <> 0 OR NEW.released_amount <> 0 THEN
      RAISE EXCEPTION 'a hold is created active with nothing captured or released'
        USING ERRCODE = 'BJ005', TABLE = 'holds';
    END IF;
  ELSIF TG_TABLE_NAME = 'earnings' THEN
    IF NEW.status NOT IN ('pending', 'held') OR NEW.mature_tx_id IS NOT NULL
       OR NEW.clawback_tx_id IS NOT NULL OR NEW.payout_record_id IS NOT NULL THEN
      RAISE EXCEPTION 'an earning is created pending or held, without maturity, clawback or payout links'
        USING ERRCODE = 'BJ005', TABLE = 'earnings';
    END IF;
  ELSIF TG_TABLE_NAME = 'payout_records' THEN
    IF NEW.status <> 'recorded' THEN
      RAISE EXCEPTION 'a payout record is created as recorded'
        USING ERRCODE = 'BJ005', TABLE = 'payout_records';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER holds_insert_guard BEFORE INSERT ON holds
  FOR EACH ROW EXECUTE FUNCTION binjari_money_record_insert_guard();
CREATE TRIGGER earnings_insert_guard BEFORE INSERT ON earnings
  FOR EACH ROW EXECUTE FUNCTION binjari_money_record_insert_guard();
CREATE TRIGGER payout_records_insert_guard BEFORE INSERT ON payout_records
  FOR EACH ROW EXECUTE FUNCTION binjari_money_record_insert_guard();
ALTER TABLE holds ENABLE ALWAYS TRIGGER holds_insert_guard;
ALTER TABLE earnings ENABLE ALWAYS TRIGGER earnings_insert_guard;
ALTER TABLE payout_records ENABLE ALWAYS TRIGGER payout_records_insert_guard;
